// AttemptSession Returned when an attempt is created, resumed or read. Everything the
// engine needs to run authoritatively.
type AttemptSession struct {
	// Answers Keyed by question id. The base for the resume merge.
	Answers map[string]Answer `json:"answers"`
	Attempt Attempt           `json:"attempt"`

	// AudioPlays Keyed by question id. **Server-authoritative** — the client renders
	// remaining plays from this, decrements optimistically, and reconciles
	// on the next fetch. A client-side counter would reset on reload and
	// make the limit meaningless (§11.4).
	AudioPlays map[string]int `json:"audioPlays"`

	// BeaconToken Opaque, valid until `deadlineAt`, **append-only event access**.
	// `navigator.sendBeacon` cannot set an `Authorization` header and the
	// 15-minute access token has usually expired by `pagehide`, so the
	// beacon carries this in its body instead. Grants no read access.
	BeaconToken string `json:"beaconToken"`

	// GroupAudioPlays Server counts keyed by frozen group recording ID, shared across all
	// members and sessions of this attempt. Different groups using the same
	// file have independent counts. Optional for historical clients.
	GroupAudioPlays *map[string]int `json:"groupAudioPlays,omitempty"`

	// Groups Frozen shared context for this attempt's version. Member IDs name
	// questions in this session; presentation order comes from questions.
	// No answer keys or recording transcripts. Only version-bound assets
	// reachable through this student's own attempt receive signed URLs.
	// Empty for historical standalone papers; optional for compatibility.
	Groups *[]StudentGroup `json:"groups,omitempty"`

	// Integrity Defaults are §10.3's, conservative on purpose — the teacher opts into
	// stricter modes per test. Whatever is enabled is stated in plain
	// Vietnamese on the intro page before the student starts (§10.2).
	Integrity IntegrityPolicy `json:"integrity"`

	// Questions Already in presentation order, shuffled server-side and stable
	// across reloads (D-02). Shuffling happens inside each section, so
	// the order of sections is the order of `sections`.
	Questions []StudentQuestion `json:"questions"`

	// RemainingAttempts Additional attempts available after this one
	RemainingAttempts *int `json:"remainingAttempts,omitempty"`

	// Sections In test order. `questions` never interleaves two sections, whatever the shuffle.
	Sections []StudentSection `json:"sections"`

	// ServerTime RFC 3339, UTC. Rendered in `Asia/Ho_Chi_Minh` by the client.
	ServerTime Timestamp `json:"serverTime"`

	// SessionId Identifies this device/tab. Every write carries it; a superseded
	// session gets `SESSION_SUPERSEDED`, which is how the first tab learns
	// it lost (§10.1, E2E 7).
	//
	//
	// Examples: 019535d9-3df7-79fb-b466-fa907fa17f9e
	SessionId Uuid `json:"sessionId"`

	// Superseded Present and true only in an answer of `getAttempt` to a tab that
	// named a session the attempt no longer has. `sessionId` is then the
	// session that tab named, `beaconToken` is empty, and every write
	// under that session answers `SESSION_SUPERSEDED`.
	Superseded *bool `json:"superseded,omitempty"`

	// TestTitle The engine's header names the paper from 1024px up (S-08).
	TestTitle string `json:"testTitle"`
}

